import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    parent = [0] * (n + 1)
    visited = [False] * (n + 1)
    stack = []

    def dfs(start_node):
        visited[start_node] = True
        stack.append(start_node)

        while stack:
            u = stack[-1]
            found_unvisited = False

            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)
                    found_unvisited = True
                    break
                elif v != parent[u]:
                    if v in stack:
                        cycle_start_idx = stack.index(v)
                        cycle_nodes = stack[cycle_start_idx:]
                        return cycle_nodes

            if not found_unvisited:
                stack.pop()

        return None

    for i in range(1, n + 1):
        if not visited[i]:
            visited_copy = [False] * (n + 1)
            stack_copy = []

            def dfs_local(start):
                visited_copy[start] = True
                stack_copy.append(start)

                while stack_copy:
                    u = stack_copy[-1]
                    found = False

                    for v in adj[u]:
                        if not visited_copy[v]:
                            visited_copy[v] = True
                            parent[v] = u
                            stack_copy.append(v)
                            found = True
                            break
                        elif v != parent.get(u, 0) and v in stack_copy:
                            idx = stack_copy.index(v)
                            return stack_copy[idx:]

                    if not found:
                        stack_copy.pop()
                return None

            cycle = dfs_local(i)
            if cycle:
                s = cycle[0]
                t = cycle[-1]
                path1 = cycle

                visited_global = [False] * (n + 1)
                for node in cycle:
                    visited_global[node] = True

                path2 = None
                path3 = None

                q = [(s, [])]
                visited_bfs = {s}

                while q:
                    curr, path = q.pop(0)
                    if curr == t:
                        if path:
                            path2 = path + [t]
                            break
                    for nxt in adj[curr]:
                        if nxt not in visited_bfs and nxt not in visited_global:
                            visited_bfs.add(nxt)
                            q.append((nxt, path + [nxt]))

                if path2:
                    visited_bfs2 = {s}
                    q2 = [(s, [])]
                    while q2:
                        curr, path = q2.pop(0)
                        if curr == t:
                            if path:
                                path3 = path + [t]
                                break
                        for nxt in adj[curr]:
                            if nxt not in visited_bfs2 and nxt not in visited_global and nxt not in set(path2):
                                visited_bfs2.add(nxt)
                                q2.append((nxt, path + [nxt]))

                    if path3:
                        print("YES")
                        print(f"{len(path1)} {' '.join(map(str, path1))}")
                        print(f"{len(path2)} {' '.join(map(str, path2))}")
                        print(f"{len(path3)} {' '.join(map(str, path3))}")
                        return

    print("NO")

